     "a": "（1）马克思的存在论是以实践论为根基的，而马克思的实践论则内在地包含着存在论维度，实践论与\n存在论的结合，构成了美学的哲学基础。\n（2）人的存在与世界的存在、人的审美感觉与现实的审美对象都是在实践中双向建构、同步发展的。\n（3）自由是从美学的哲学基础向美学的内在问题过渡的中介概念，也是从人的实践一存在向审美现象、\n审美活动过渡的中介环节。"
